// =====================================================
// SCORING MATRIX — EDIT ONLY THIS CONFIG BLOCK
// Weights follow a 100-point matrix:
// budget 25 · timeline 20 · area 15 · property type 15
// financing 10 · info provided 10 · visit availability 5
// =====================================================
const CONFIG = {
  presupuestoMin: 150000,          // agency's minimum ticket (EUR)
  presupuestoMax: 3000000,         // agency's maximum ticket (EUR)
  zonasCubiertas: ['marbella', 'malaga', 'málaga', 'estepona', 'mijas', 'fuengirola', 'benalmadena', 'benalmádena'],
  tipologiasDisponibles: ['apartamento', 'piso', 'atico', 'ático', 'villa', 'casa', 'chalet', 'adosado'],
  pesos: { presupuesto: 25, plazo: 20, zona: 15, tipologia: 15, financiacion: 10, informacion: 10, visita: 5 },
  tiers: { prioritario: 80, cualificado: 60, seguimiento: 35 }
};
// =====================================================

const d = $json.output || {};
const entrada = $('Set Lead Fields').item.json;
let score = 0;
const pendientes = [];

// Timeline in months, computed DETERMINISTICALLY here (never by the AI):
// plazo_fecha (YYYY-MM) wins; plazo_meses (relative duration) is the fallback.
function mesesDesdeHoy(plazoMeses, plazoFecha) {
  if (plazoFecha && /^\d{4}-\d{2}$/.test(String(plazoFecha))) {
    const [y, m] = String(plazoFecha).split('-').map(Number);
    const diff = (y - $now.year) * 12 + (m - $now.month);
    return Math.max(0, diff);
  }
  if (plazoMeses !== null && plazoMeses !== undefined && plazoMeses !== '' && !isNaN(Number(plazoMeses))) {
    return Math.max(0, Math.round(Number(plazoMeses)));
  }
  return null;
}

// 1. Budget fit (0–25)
const presupuesto = Number(d.presupuesto) || null;
if (presupuesto) {
  if (presupuesto >= CONFIG.presupuestoMin && presupuesto <= CONFIG.presupuestoMax) {
    score += CONFIG.pesos.presupuesto;
  } else {
    score += Math.round(CONFIG.pesos.presupuesto * 0.3); // out of range: partial credit
  }
} else {
  pendientes.push('presupuesto');
}

// 2. Timeline (0–20)
const plazo = mesesDesdeHoy(d.plazo_meses, d.plazo_fecha);
if (plazo !== null) {
  if (plazo <= 3) score += CONFIG.pesos.plazo;
  else if (plazo <= 6) score += Math.round(CONFIG.pesos.plazo * 0.6);
  else if (plazo <= 12) score += Math.round(CONFIG.pesos.plazo * 0.3);
} else {
  pendientes.push('plazo');
}

// 3. Area covered (0–15)
const zona = String(d.zona || '').toLowerCase();
if (zona) {
  if (CONFIG.zonasCubiertas.some(z => zona.includes(z))) score += CONFIG.pesos.zona;
} else {
  pendientes.push('zona');
}

// 4. Property type available (0–15)
const tipologia = String(d.tipologia || '').toLowerCase();
if (tipologia) {
  if (CONFIG.tipologiasDisponibles.some(t => tipologia.includes(t))) score += CONFIG.pesos.tipologia;
} else {
  pendientes.push('tipología');
}

// 5. Financing (0–10)
const fin = String(d.financiacion || 'sin datos').toLowerCase();
if (fin === 'preparada' || fin === 'no necesita') {
  score += CONFIG.pesos.financiacion;
} else if (fin === 'sin datos' || fin === '') {
  pendientes.push('financiación');
}

// 6. Information provided (0–10, proportional)
const campos = ['intencion', 'zona', 'tipologia', 'presupuesto'];
let rellenos = campos.filter(c => d[c] !== null && d[c] !== undefined && d[c] !== '').length;
if (plazo !== null) rellenos++;
score += Math.round(CONFIG.pesos.informacion * (rellenos / 5));

// 7. Visit availability (0–5)
if (d.disponibilidad_visita === true) score += CONFIG.pesos.visita;

score = Math.min(score, 100);

// Priority tier + recommended action (sellers follow a different flow)
const intencion = String(d.intencion || '').toLowerCase();
let prioridad, accion;
if (intencion === 'vender') {
  prioridad = 'vendedor';
  accion = 'Derivar al equipo de captación y proponer valoración';
} else if (score >= CONFIG.tiers.prioritario) {
  prioridad = 'prioritario';
  accion = 'Contactar hoy mismo y proponer llamada o visita';
} else if (score >= CONFIG.tiers.cualificado) {
  prioridad = 'cualificado';
  accion = 'Enviar propiedades relevantes y proponer llamada esta semana';
} else if (score >= CONFIG.tiers.seguimiento) {
  prioridad = 'seguimiento';
  accion = 'Pedir los datos pendientes y programar seguimiento';
} else {
  prioridad = 'incompleto';
  accion = 'Enviar 2-3 preguntas cortas de cualificación antes de asignar agente';
}

return [{
  json: {
    fecha: new Date().toISOString(),
    nombre: entrada.nombre || '',
    telefono: entrada.telefono || '',
    canal: entrada.canal || 'webhook',
    mensaje: entrada.mensaje || '',
    intencion: d.intencion || '',
    zona: d.zona || '',
    tipologia: d.tipologia || '',
    dormitorios: (d.dormitorios ?? '') === null ? '' : (d.dormitorios ?? ''),
    presupuesto: presupuesto ?? '',
    plazo_meses: plazo ?? '',
    financiacion: d.financiacion || 'sin datos',
    idioma: d.idioma || '',
    disponibilidad_visita: d.disponibilidad_visita === true ? 'sí' : '',
    score: score,
    prioridad: prioridad,
    accion_recomendada: accion,
    datos_pendientes: pendientes.join(', ')
  }
}];
